{
  "env": {
    "DISABLE_AUTOUPDATER": "0",
    "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS": "1"
  },
  "hooks": {
    "SessionStart": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "claude plugin marketplace update yorrick 2>/dev/null; claude plugin marketplace update claude-plugins-official 2>/dev/null; claude plugin update dev-loop@yorrick 2>/dev/null; claude plugin update superpowers@claude-plugins-official 2>/dev/null; echo 'Plugin update check complete'",
            "timeout": 30
          }
        ]
      }
    ]
  },
  "enabledPlugins": {
    "code-simplifier@claude-plugins-official": true,
    "code-review@claude-plugins-official": true,
    "security-guidance@claude-plugins-official": false,
    "feature-dev@claude-plugins-official": true,
    "self-improve-skill@yorrick": true,
    "pyright-lsp@claude-plugins-official": true,
    "commit-commands@claude-plugins-official": true,
    "plugin-dev@claude-plugins-official": true,
    "linear@claude-plugins-official": true,
    "frontend-design@claude-plugins-official": true,
    "ralph-loop@claude-plugins-official": true,
    "superpowers@claude-plugins-official": true,
    "skill-creator@claude-plugins-official": true,
    "dev-loop@yorrick": true,
    "aws-serverless@agent-plugins-for-aws": true
  },
  "extraKnownMarketplaces": {
    "agent-plugins-for-aws": {
      "source": {
        "source": "github",
        "repo": "awslabs/agent-plugins"
      }
    }
  },
  "alwaysThinkingEnabled": false,
  "autoUpdatesChannel": "latest",
  "minimumVersion": "2.1.19",
  "skipDangerousModePermissionPrompt": true,
  "effortLevel": "high",
  "feedbackSurveyState": {
    "lastShownTime": 1754001153244
  }
}
